 g=Setup();RebirthStationQueuedDiscoveryAuthorization.Discovery=true;RebirthStationQueuedDiscoveryAuthorization.Allowed=false;Check(!RebirthStationOpenPaidExecutionLease.TryEnter(g,out _),"bound discovery denied still denied");
 Console.WriteLine($"PASS {n}: actual inactive lease + original completion source; installed native while/UpdateTick extraction, native UI/lock/policy/fuel adapters explicit.");}}
